import{_ as e,o as i,c as l,a5 as t}from"./chunks/framework.C1a7WKBV.js";const u=JSON.parse('{"title":"通用 AI 编程方法论","description":"用项目规则、上下文管理和任务拆解，让任何 AI 编程客户端的产出质量翻倍。","frontmatter":{"title":"通用 AI 编程方法论","description":"用项目规则、上下文管理和任务拆解，让任何 AI 编程客户端的产出质量翻倍。"},"headers":[],"relativePath":"tips/ai-coding-principles.md","filePath":"tips/ai-coding-principles.md","lastUpdated":1788838685000}'),o={name:"tips/ai-coding-principles.md"};function r(s,a,n,d,h,c){return i(),l("div",null,[...a[0]||(a[0]=[t(`<h1 id="通用-ai-编程方法论" tabindex="-1">通用 AI 编程方法论 <a class="header-anchor" href="#通用-ai-编程方法论" aria-label="Permalink to &quot;通用 AI 编程方法论&quot;">​</a></h1><p>这套方法论与客户端无关，Claude Code、Codex、Cursor 都适用，是《<a href="/ai-handbook/tips/roadmap">从零到驾驭 AI：成长路径</a>》第四阶段（会协作）的展开。核心就四件事：给 AI 立规矩、喂对上下文、拆小任务、小步验证。</p><h2 id="_1-用项目规则文件给-ai-立规矩" tabindex="-1">1. 用项目规则文件给 AI 立规矩 <a class="header-anchor" href="#_1-用项目规则文件给-ai-立规矩" aria-label="Permalink to &quot;1. 用项目规则文件给 AI 立规矩&quot;">​</a></h2><h3 id="_1-1-为什么需要规则文件" tabindex="-1">1.1 为什么需要规则文件 <a class="header-anchor" href="#_1-1-为什么需要规则文件" aria-label="Permalink to &quot;1.1 为什么需要规则文件&quot;">​</a></h3><p>AI 每次对话都是&quot;新同事入职&quot;。没有规则文件，它每次都要重新猜你的技术栈、代码风格和禁忌。规则文件相当于一份常驻的入职手册，每次会话自动注入。</p><h3 id="_1-2-放什么内容" tabindex="-1">1.2 放什么内容 <a class="header-anchor" href="#_1-2-放什么内容" aria-label="Permalink to &quot;1.2 放什么内容&quot;">​</a></h3><ul><li>项目技术栈与版本（如 <code>Vite + Vue 3 + TypeScript</code>）。</li><li>目录结构约定，说明&quot;什么代码放哪里&quot;。</li><li>编码规范：命名、注释、测试要求。</li><li>禁止事项：不要改哪些文件、不要引入哪些依赖、不要删注释。</li><li>常用命令：构建、测试、启动的准确命令。</li></ul><h3 id="_1-3-放在哪里" tabindex="-1">1.3 放在哪里 <a class="header-anchor" href="#_1-3-放在哪里" aria-label="Permalink to &quot;1.3 放在哪里&quot;">​</a></h3><ul><li>Claude Code 读取 <code>CLAUDE.md</code>（项目根目录），也遵循 <code>AGENTS.md</code>。</li><li>Codex 读取 <code>AGENTS.md</code>。</li><li>Cursor 支持 <code>.cursorrules</code> 或 <code>.cursor/rules/</code> 目录。</li></ul><p>规则文件保持在 100 行以内，写成&quot;指令&quot;而不是&quot;散文&quot;。太长会被稀释，AI 反而抓不住重点。</p><h3 id="_1-4-迭代规则" tabindex="-1">1.4 迭代规则 <a class="header-anchor" href="#_1-4-迭代规则" aria-label="Permalink to &quot;1.4 迭代规则&quot;">​</a></h3><p>发现 AI 犯了同一个错两次，就把这条纠正写进规则文件。规则文件是活的文档，随项目成长。</p><h2 id="_2-管理好上下文窗口" tabindex="-1">2. 管理好上下文窗口 <a class="header-anchor" href="#_2-管理好上下文窗口" aria-label="Permalink to &quot;2. 管理好上下文窗口&quot;">​</a></h2><h3 id="_2-1-上下文决定质量" tabindex="-1">2.1 上下文决定质量 <a class="header-anchor" href="#_2-1-上下文决定质量" aria-label="Permalink to &quot;2.1 上下文决定质量&quot;">​</a></h3><p>AI 只&quot;看得见&quot;当前上下文里的内容。上下文塞满了无关代码，回答质量就会下降；关键文件没进去，它就开始瞎猜。</p><h3 id="_2-2-实用做法" tabindex="-1">2.2 实用做法 <a class="header-anchor" href="#_2-2-实用做法" aria-label="Permalink to &quot;2.2 实用做法&quot;">​</a></h3><ul><li>在项目根目录启动会话，而不是家目录，避免 AI 找不到文件。</li><li>让 AI 先用搜索定位相关文件，再读入，而不是一次性贴大量代码。</li><li>新任务开新会话。上一任务的历史会污染下一任务的判断。</li><li>长会话中主动总结：让 AI 输出当前进度与决策，开新会话后粘贴进去。</li></ul><h3 id="_2-3-识别上下文被污染的信号" tabindex="-1">2.3 识别上下文被污染的信号 <a class="header-anchor" href="#_2-3-识别上下文被污染的信号" aria-label="Permalink to &quot;2.3 识别上下文被污染的信号&quot;">​</a></h3><p>AI 开始重复问你说过的事、忘记早先的约束、或引用不存在的代码，就该清理上下文或重启会话了。</p><h2 id="_3-把大任务拆成小任务" tabindex="-1">3. 把大任务拆成小任务 <a class="header-anchor" href="#_3-把大任务拆成小任务" aria-label="Permalink to &quot;3. 把大任务拆成小任务&quot;">​</a></h2><h3 id="_3-1-为什么拆" tabindex="-1">3.1 为什么拆 <a class="header-anchor" href="#_3-1-为什么拆" aria-label="Permalink to &quot;3.1 为什么拆&quot;">​</a></h3><p>一次性让 AI&quot;实现整个功能&quot;，生成 500 行代码后出错的概率极高，而且错误藏得深。小任务每次生成几十行，出错立刻能发现。</p><h3 id="_3-2-拆法" tabindex="-1">3.2 拆法 <a class="header-anchor" href="#_3-2-拆法" aria-label="Permalink to &quot;3.2 拆法&quot;">​</a></h3><ol><li>先让 AI 输出实现方案（改哪些文件、分几步），确认后再动手。</li><li>每步只做一件事：一个函数、一个组件、一次重构。</li><li>每步结束立即构建或跑测试，绿色了再进行下一步。</li><li>遇到偏差，当场纠正，不要攒到最后。</li></ol><h3 id="_3-3-好的任务描述模板" tabindex="-1">3.3 好的任务描述模板 <a class="header-anchor" href="#_3-3-好的任务描述模板" aria-label="Permalink to &quot;3.3 好的任务描述模板&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在 src/api/user.ts 中新增 updateUser 函数：</span></span>
<span class="line"><span>- 输入：UpdateUserPayload 类型（见 src/types/user.ts）</span></span>
<span class="line"><span>- 调用 PATCH /api/users/:id</span></span>
<span class="line"><span>- 参考同文件中 getUser 的写法，包括错误处理</span></span>
<span class="line"><span>- 完成后运行 npm run typecheck</span></span></code></pre></div><p>指明位置、输入输出、参照物和验证方式，AI 一次命中的概率大幅提升。</p><h2 id="_4-小步迭代与验证闭环" tabindex="-1">4. 小步迭代与验证闭环 <a class="header-anchor" href="#_4-小步迭代与验证闭环" aria-label="Permalink to &quot;4. 小步迭代与验证闭环&quot;">​</a></h2><h3 id="_4-1-永远不要直接相信生成结果" tabindex="-1">4.1 永远不要直接相信生成结果 <a class="header-anchor" href="#_4-1-永远不要直接相信生成结果" aria-label="Permalink to &quot;4.1 永远不要直接相信生成结果&quot;">​</a></h3><p>AI 生成的代码要经过三道检查：能否构建、逻辑是否正确、是否符合项目风格。构建能挡住语法与类型错误，逻辑和风格需要你读一遍 diff。</p><h3 id="_4-2-建立验证习惯" tabindex="-1">4.2 建立验证习惯 <a class="header-anchor" href="#_4-2-建立验证习惯" aria-label="Permalink to &quot;4.2 建立验证习惯&quot;">​</a></h3><ul><li>让 AI 修改后主动运行构建或测试，而不是只&quot;看起来对&quot;。</li><li>用 git diff 审查每次改动，发现多余改动立刻要求回退。</li><li>让 AI 解释关键改动的原因，解释不清的实现往往有问题。</li></ul><h3 id="_4-3-处理连续失败" tabindex="-1">4.3 处理连续失败 <a class="header-anchor" href="#_4-3-处理连续失败" aria-label="Permalink to &quot;4.3 处理连续失败&quot;">​</a></h3><p>同一个问题修三轮还没好，说明方向错了。停下来：让 AI 总结目前的尝试与失败原因，换个思路重新拆任务，而不是继续在错误方向上加补丁。</p><h2 id="_5-一页速查" tabindex="-1">5. 一页速查 <a class="header-anchor" href="#_5-一页速查" aria-label="Permalink to &quot;5. 一页速查&quot;">​</a></h2><ul><li>规则文件常驻项目根目录，100 行以内，持续迭代。</li><li>新任务开新会话，长会话主动总结续接。</li><li>大任务先要方案，拆成小步，步步验证。</li><li>描述任务说清：位置、输入输出、参照物、验证命令。</li><li>修三轮不过就换方向。</li></ul><p>相关阅读：《<a href="/ai-handbook/tips/prompt-secrets">Prompt 提示词秘籍</a>》（把任务描述写到位）、《<a href="/ai-handbook/tips/claude-code-advanced">Claude Code 进阶玩法</a>》（把重复动作自动化）、《<a href="/ai-handbook/tips/token-efficiency">效率与省钱技巧</a>》（同一习惯的费用视角）。</p>`,37)])])}const _=e(o,[["render",r]]);export{u as __pageData,_ as default};
